// ================================================================
// Code â€” Explode Asset List (v3.1 Standardized)
// 
// Parses Art Director output into individual asset items
// Uses snake_case keys throughout
// ================================================================

const agentRaw =
  $('Agent â€” The Art Director').first().json.output ||
  $('Agent â€” The Art Director').first().json.text ||
  '';

// Clean and parse JSON
const cleanJson = String(agentRaw)
  .replace(/```json/gi, '')
  .replace(/```/g, '')
  .trim();

let parsed;
try {
  parsed = JSON.parse(cleanJson);
} catch (e) {
  throw new Error(`Failed to parse Art Director JSON: ${e.message}\n\nRaw output: ${cleanJson.substring(0, 500)}`);
}

if (!parsed.assets || !Array.isArray(parsed.assets)) {
  throw new Error('Art Director output missing "assets" array');
}

// Get parent context from the project processor loop (already normalized)
const loopItem = $('Loop â€” Project Processor').first().json;

// Extract context using snake_case keys (from normalized data)
const copyId = loopItem.copy_id || "UNKNOWN";
const imageId = loopItem.image_id || `${loopItem.traffic_leak_record_id}-IMAGES`;
const folderId = loopItem.drive_folder_id || null;
const folderUrl = loopItem.drive_folder_url || null;
const trafficLeakRecordId = loopItem.traffic_leak_record_id || null;
const parentTitle = loopItem.video_title || "Asset";
const visualTheme = parsed.visual_theme || "";

// Create a sanitized title prefix for filenames (max 20 chars)
const titlePrefix = parentTitle
  .substring(0, 20)
  .replace(/[^a-z0-9]/gi, '_')
  .replace(/_+/g, '_')
  .replace(/^_|_$/g, '');

// Return one item per asset for the generation loop
return parsed.assets.map((asset, index) => ({
  json: {
    // â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    // ASSET-SPECIFIC FIELDS (from Art Director)
    // â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    asset_type: asset.type || `Asset_${index + 1}`,
    model_id: asset.model_id || "black-forest-labs/flux.2-pro",
    prompt: asset.prompt || "",
    aspect_ratio: asset.aspect_ratio || "16:9",
    filename_suffix: asset.filename_suffix || `_asset_${String(index + 1).padStart(2, '0')}`,

    // â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    // COMPUTED FIELDS
    // â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    drive_filename: `${titlePrefix}${asset.filename_suffix || `_asset_${String(index + 1).padStart(2, '0')}`}.png`,

    // â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    // PARENT CONTEXT (for Drive save and tracking)
    // â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    parent_title: parentTitle,
    title_prefix: titlePrefix,
    copy_id: copyId,
    image_id: imageId,
    drive_folder_id: folderId,
    drive_folder_url: folderUrl,
    traffic_leak_record_id: trafficLeakRecordId,
    visual_theme: visualTheme,

    // â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    // ASSET COUNTERS
    // â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    asset_index: index + 1,
    total_assets: parsed.assets.length
  }
}));

const response = items[0].json;
let binaryData = null;
let mimeType = 'image/png';
const filenameSuffix = ($('Loop â€” Asset Generator').item.json.filename_suffix) || '_image';

// --- HELPER 1: Recursive Search for Image Data ---
function findImageString(obj) {
    if (!obj) return null;

    // A. If it's a string, check if it looks like an image
    if (typeof obj === 'string') {
        // Priority 1: Standard Data URI (with prefix)
        if (obj.match(/^data:image\/.*;base64,/)) return obj;
        // Priority 2: Direct URL (ignoring airtable/system links)
        if (obj.match(/^https?:\/\/.*(png|jpg|jpeg|webp)/i) && !obj.includes('airtable')) return obj;
        // Priority 3: Embedded Markdown/Text URL
        const embeddedUrl = obj.match(/(https?:\/\/[^\s)"']+|data:image\/[a-zA-Z]+;base64,[^\s)"']+)/);
        if (embeddedUrl && !obj.includes('airtable')) return embeddedUrl[0];

        return null;
    }

    // B. If it's an Object/Array, traverse it
    if (typeof obj === 'object') {
        // --- CRITICAL FIX: Trust specific keys for raw Base64 ---
        if (obj.b64_json && typeof obj.b64_json === 'string') return obj.b64_json;
        if (obj.base64 && typeof obj.base64 === 'string') return obj.base64;

        // Standard URL check
        if (obj.url && typeof obj.url === 'string' && !obj.url.includes('airtable')) return findImageString(obj.url);

        // Otherwise, recursive scan
        for (const key in obj) {
            // Skip large system keys
            if (key === 'cachedResultUrl' || key === 'input' || key === 'context' || key === 'headers') continue;

            const found = findImageString(obj[key]);
            if (found) return found;
        }
    }
    return null;
}

// --- HELPER 2: Parse Base64 ---
function parseDataUri(uri) {
    const matches = uri.match(/^data:(.+);base64,(.+)$/);
    if (matches) {
        return { mime: matches[1], data: matches[2] };
    }
    // Fallback: Assume raw PNG data
    return { mime: 'image/png', data: uri }; 
}

// --- MAIN EXECUTION ---
try {
    const rawValue = findImageString(response);

    if (!rawValue) {
        const keys = Object.keys(response).join(', ');
        throw new Error(`Deep Search failed. No image found in keys: [${keys}].`);
    }

    // Convert to Binary
    if (rawValue.startsWith('http')) {
        const imgReq = await fetch(rawValue);
        const buf = await imgReq.arrayBuffer();
        binaryData = Buffer.from(buf).toString('base64');
        mimeType = imgReq.headers.get('content-type') || mimeType;
    } else {
        const parsed = parseDataUri(rawValue);
        binaryData = parsed.data;
        mimeType = parsed.mime;
    }

    // Final validation
    if (!binaryData || binaryData.length < 100) {
        throw new Error("Image data was found but appears corrupted or empty.");
    }

    // Get loop context using snake_case keys
    const loopContext = $('Loop â€” Asset Generator').item.json;

    return [{
        json: {
            // â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
            // PASS THROUGH ALL LOOP CONTEXT
            // â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
            ...loopContext,

            // â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
            // EXTRACTION RESULTS
            // â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
            status: "success",
            source_type: rawValue.startsWith('http') ? 'url' : 'base64'
        },
        binary: {
            data: {
                data: binaryData,
                mimeType: mimeType,
                fileName: `generated${filenameSuffix}.${mimeType.split('/')[1]}`
            }
        }
    }];

} catch (error) {
    // Get loop context for error tracking
    const loopContext = $('Loop â€” Asset Generator').item.json;

    return [{
        json: {
            ...loopContext,
            status: "error",
            error_message: error.message || "Unknown error occurred"
        }
    }];
}

