// 
// Filters out assets that already exist (idempotency)
// Uses snake_case keys
// ================================================================

const plannedItems = $('Code â€” Explode Asset List').all();

// Get existing keys (if checking against Airtable or Drive)
// For now, pass through all items (implement dedup logic as needed)

return plannedItems;

// ================================================================
// Code â€” Merge Folder + Context (v2.1 Standardized)
// 
// Merges folder creation result with normalized context
// Uses snake_case keys throughout
// ================================================================

const incoming = $json;
const original = $('If').item.json;

if (!original) {
  throw new Error('Missing context from If node');
}

// Folder ID: either from existing context OR from newly created folder
const folderId =
  original.drive_folder_id ||
  (incoming && incoming.id ? incoming.id : null);

const folderUrl = folderId 
  ? `https://drive.google.com/drive/folders/${folderId}` 
  : null;

return [{
  json: {
    // Pass through entire original normalized context
    ...original,

    // â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    // DRIVE DATA (updated)
    // â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    drive_folder_id: folderId,
    drive_folder_url: folderUrl,

    // â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    // STAGE TRACKING
    // â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    _stage: "IMAGES_FOLDER_READY"
  }
}];

// ================================================================
// Code â€” Normalize Copy + Traffic Leak Data (v1.0)
// 
// Transforms Airtable response to standardized snake_case contract.
// Works with EITHER Copy table OR Traffic Leaks table as source.
// ================================================================

const items = $input.all();

return items.map(item => {
  const fields = item.json.fields || item.json;
  const recordId = item.json.id || fields.id;

  // â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  // DETECT SOURCE TABLE
  // Copy records have "Copy ID", Traffic Leak records have "Leak ID"
  // â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  const isFromCopy = !!fields['Copy ID'];
  const isFromTrafficLeak = !!fields['Leak ID'];

  // â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  // EXTRACT IDs BASED ON SOURCE
  // â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  let trafficLeakRecordId, copyId, copyRecordId;

  if (isFromCopy) {
    // Source is Copy table
    copyRecordId = recordId;
    copyId = fields['Copy ID'] || '';
    // Traffic Leak is a linked field (returns array of record IDs)
    trafficLeakRecordId = Array.isArray(fields['Traffic Leak']) 
      ? fields['Traffic Leak'][0] 
      : fields['Traffic Leak'] || null;
  } else {
    // Source is Traffic Leaks table
    trafficLeakRecordId = recordId;
    // Copy Generated is a linked field
    copyRecordId = Array.isArray(fields['Copy Generated']) 
      ? fields['Copy Generated'][0] 
      : fields['Copy Generated'] || null;
    // Derive Copy ID from Video ID
    const videoId = Array.isArray(fields['Video']) 
      ? fields['Video'][0] 
      : fields['Video ID'] || fields['Leak ID']?.split('v=')[1] || '';
    copyId = `${videoId}-COPY`;
  }

  // â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  // DERIVE IMAGE ID
  // â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  const imageId = `${trafficLeakRecordId}-IMAGES`;

  return {
    json: {
      // â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
      // AIRTABLE RECORD IDs (critical for linking)
      // â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
      traffic_leak_record_id: trafficLeakRecordId,
